if (size <= 1) return;
int max = arr[0];
for (int i = 1; i < size; ++i) {
    if (arr[i] > max) max = arr[i];
}
int exp = 1;
while (max / exp > 0) {
    int count[10] = {0};
    for (int i = 0; i < size; ++i) {
        int digit = (arr[i] / exp) % 10;
        ++count[digit];
    }
    for (int i = 1; i < 10; ++i) {
        count[i] += count[i-1];
    }
    int* output = new int[size];
    for (int i = size - 1; i >= 0; --i) {
        int digit = (arr[i] / exp) % 10;
        output[--count[digit]] = arr[i];
    }
    for (int i = 0; i < size; ++i) {
        arr[i] = output[i];
    }
    delete[] output;

